package com.meddibuddy.upload;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.util.StringUtils;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.io.IOException;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/admin/uploads") public class ImageUploadController {
 private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp","image/gif");private static final Set<String> EXTENSIONS=Set.of(".jpg",".jpeg",".png",".webp",".gif");private final Path uploadDirectory;
 public ImageUploadController(@Value("${app.upload-dir:uploads}") String path){uploadDirectory=Paths.get(path).toAbsolutePath().normalize();}
 @PostMapping(consumes="multipart/form-data") public Map<String,String> upload(@RequestPart("file") MultipartFile file){if(file.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an image first");if(file.getSize()>10L*1024*1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Image must be 10 MB or smaller");String type=file.getContentType();if(type==null||!TYPES.contains(type.toLowerCase()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Use a JPG, PNG, WebP, or GIF image");String original=StringUtils.cleanPath(Objects.requireNonNullElse(file.getOriginalFilename(),"photo.jpg"));int dot=original.lastIndexOf('.');String ext=dot<0?"":original.substring(dot).toLowerCase();if(!EXTENSIONS.contains(ext))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported image file extension");String name=UUID.randomUUID()+ext;try{Files.createDirectories(uploadDirectory);Path destination=uploadDirectory.resolve(name).normalize();if(!destination.startsWith(uploadDirectory))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid filename");file.transferTo(destination);return Map.of("url","/uploads/"+name);}catch(IOException e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Could not save the image");}}
}
